// Flux Dev fp8 txt2img workflow
// Requires: flux1-dev-fp8.safetensors, clip_l.safetensors, t5xxl_fp8_e4m3fn.safetensors, ae.safetensors
const prompt = $input.item.json.prompt || "a product shot, clean white background, professional lighting";
const seed = Math.floor(Math.random() * 1e14);

const workflow = {
  "1": { "inputs": { "unet_name": "flux1-dev-fp8.safetensors", "weight_dtype": "fp8_e4m3fn" }, "class_type": "UNETLoader" },
  "2": { "inputs": { "clip_name1": "clip_l.safetensors", "clip_name2": "t5xxl_fp8_e4m3fn.safetensors", "type": "flux", "device": "default" }, "class_type": "DualCLIPLoader" },
  "3": { "inputs": { "vae_name": "ae.safetensors" }, "class_type": "VAELoader" },
  "4": { "inputs": { "text": prompt, "clip": ["2", 0] }, "class_type": "CLIPTextEncode" },
  "5": { "inputs": { "width": 1024, "height": 1024, "batch_size": 1 }, "class_type": "EmptyLatentImage" },
  "6": { "inputs": { "noise": ["7", 0], "guider": ["8", 0], "sampler": ["9", 0], "sigmas": ["10", 0], "latent_image": ["5", 0] }, "class_type": "SamplerCustomAdvanced" },
  "7": { "inputs": { "noise_seed": seed }, "class_type": "RandomNoise" },
  "8": { "inputs": { "model": ["1", 0], "conditioning": ["4", 0] }, "class_type": "BasicGuider" },
  "9": { "inputs": { "sampler_name": "euler" }, "class_type": "KSamplerSelect" },
  "10": { "inputs": { "model": ["1", 0], "steps": 20, "denoise": 1.0, "scheduler": "simple" }, "class_type": "BasicScheduler" },
  "11": { "inputs": { "samples": ["6", 0], "vae": ["3", 0] }, "class_type": "VAEDecode" },
  "12": { "inputs": { "filename_prefix": "flux-n8n", "images": ["11", 0] }, "class_type": "SaveImage" }
};
return [{ json: { prompt: workflow } }];
